class TeachingSelectionCases { static void discuss(){System.out.println("Use ArrayList for indexed access, LinkedList for frequent iterator-local edits, hash table for expected O(1) lookup, tree for ordered range queries, heap for repeated min/max, graph for relationships, union-find for connectivity, trie or suffix-array-style index for prefixes/substrings, k-d tree for spatial range search, treap for randomized balance, pairing heap for merge-heavy priorities.");} }
